SELECT pp.id AS paper_id, pp.symbol, pp.opened_at AS paper_opened, w.id AS wmp_id, w.opened_at AS wmp_opened, w.status, w.entry_stage, w.allocated_position_percent, w.entry_quality_score, w.average_entry_price_usdt, w.total_cost_usdt FROM crypto_ai.paper_position pp LEFT JOIN crypto_ai.wallet_managed_position w ON w.symbol = pp.symbol AND w.opened_at BETWEEN pp.opened_at - INTERVAL 15 SECOND AND pp.opened_at + INTERVAL 15 SECOND WHERE pp.id IN (137,143,158,162,172,182) ORDER BY pp.id LIMIT 30